changeSet.sql:
INSERT INTO role (name, active, deleted, version, created_at, updated_at, description_uz, description_ru, description_uz_cyril, description_kaa) VALUES ('isemid_assistant_epidemiologist', true, false, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 'Epidemiolog mutaxassisga tekshirish va tahlil ishlarida yordam beradigan, ma''lumotlarni tizimga kiritadigan hamda biriktirilgan tibbiy kartalarni rasmiylashtiradigan epidemiolog yordamchisi.', 'Помощник эпидемиолога, оказывающий содействие специалисту-эпидемиологу в обследовании и анализе, вносящий данные в систему и оформляющий прикреплённые медицинские карты.', 'Эпидемиолог мутахассисга текшириш ва таҳлил ишларида ёрдам берадиган, маълумотларни тизимга киритадиган ҳамда бириктирилган тиббий карталарни расмийлаштирадиган эпидемиолог ёрдамчиси.', 'Epidemiolog qánigesine tekseriw hám tallaw jumıslarında járdem beretuǵın, maǵlıwmatlardı sistemaǵa kirgizetuǵın hám biriktirilgen medicinalıq kartalardı rásmiylestiretuǵın epidemiolog járdemshisi.') ON CONFLICT (name) DO UPDATE SET description_uz = EXCLUDED.description_uz, description_ru = EXCLUDED.description_ru, description_uz_cyril = EXCLUDED.description_uz_cyril, description_kaa = EXCLUDED.description_kaa;
INSERT INTO role (name, active, deleted, version, created_at, updated_at, description_uz, description_ru, description_uz_cyril, description_kaa) VALUES ('isemid_epidim_head', true, false, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 'Epidemiologiya va immunoprofilaktika bo''limi ishini nazorat qiluvchi, statistik tahlillarni yurituvchi hamda shoshilinch xabarnomalarni qabul qiluvchi bo''lim mudiri.', 'Заведующий отделом эпидемиологии и иммунопрофилактики, осуществляющий контроль работы отдела, ведущий статистический анализ и принимающий экстренные извещения.', 'Эпидемиология ва иммунопрофилактика бўлими ишини назорат қилувчи, статистик таҳлилларни юритувчи ҳамда шошилинч хабарномаларни қабул қилувчи бўлим мудири.', 'Epidemiologiya hám immunoprofilaktika bólimi jumısın baqlaytuǵın, statistikalıq tallawlardı júrgizetuǵın hám tez xabarlamalardı qabıl etetuǵın bólim baslıǵı.') ON CONFLICT (name) DO UPDATE SET description_uz = EXCLUDED.description_uz, description_ru = EXCLUDED.description_ru, description_uz_cyril = EXCLUDED.description_uz_cyril, description_kaa = EXCLUDED.description_kaa;
INSERT INTO role (name, active, deleted, version, created_at, updated_at, description_uz, description_ru, description_uz_cyril, description_kaa) VALUES ('isemid_head_doctor', true, false, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 'Muassasa faoliyatini umumiy nazorat qiluvchi, shoshilinch xabarnomalar va hisobotlarni ko''rib chiqadigan bosh shifokor.', 'Главный врач учреждения, осуществляющий общий контроль деятельности организации и рассматривающий экстренные извещения и отчёты.', 'Муассаса фаолиятини умумий назорат қилувчи, шошилинч хабарномалар ва ҳисоботларни кўриб чиқадиган бош шифокор.', 'Mekemeniń jumısın tolıq baqlaytuǵın, tez xabarlamalar hám esabatlardı kóretuǵın bas dári-ger.') ON CONFLICT (name) DO UPDATE SET description_uz = EXCLUDED.description_uz, description_ru = EXCLUDED.description_ru, description_uz_cyril = EXCLUDED.description_uz_cyril, description_kaa = EXCLUDED.description_kaa;
INSERT INTO role (name, active, deleted, version, created_at, updated_at, description_uz, description_ru, description_uz_cyril, description_kaa) VALUES ('isemid_general_practitioner', true, false, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 'Bemorlarni birlamchi ko''rikdan o''tkazadigan hamda yuqumli kasallik aniqlanganda yangi shoshilinch xabarnoma (058-shakl) yaratib yuboradigan umumiy amaliyot shifokori.', 'Врач общей практики, проводящий первичный осмотр пациентов и создающий/направляющий новое экстренное извещение (форма 058) при выявлении инфекционного заболевания.', 'Беморларни бирламчи кўрикдан ўтказадиган ҳамда юқумли касаллик аниқланганда янги шошилинч хабарнома (058-шакл) яратиб юборадиган умумий амалиёт шифокори.', 'Naw qaslardı dáslepki kóriwden ótkizetuǵın hám juqpalı kesellik anıqlanǵanda jańa tez xabarlama (058-forma) jaratıp jiberetuǵın ulıwma ámeliyat dári-geri.') ON CONFLICT (name) DO UPDATE SET description_uz = EXCLUDED.description_uz, description_ru = EXCLUDED.description_ru, description_uz_cyril = EXCLUDED.description_uz_cyril, description_kaa = EXCLUDED.description_kaa;
INSERT INTO role (name, active, deleted, version, created_at, updated_at, description_uz, description_ru, description_uz_cyril, description_kaa) VALUES ('isemid_qr_user', true, false, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 'Faqat QR-kod orqali bemor yoki hujjat ma''lumotlarini tekshirish huquqiga ega bo''lgan cheklangan foydalanuvchi.', 'Ограниченный пользователь, имеющий право проверки данных пациента или документа только посредством сканирования QR-кода.', 'Фақат QR-код орқали бемор ёки ҳужжат маълумотларини текшириш ҳуқуқига эга бўлган чекланган фойдаланувчи.', 'Tek QR-kod arqalı naw qas yamasa hújjet maǵlıwmatların tekseriw huqıqına iye sheklengen paydalanıwshı.') ON CONFLICT (name) DO UPDATE SET description_uz = EXCLUDED.description_uz, description_ru = EXCLUDED.description_ru, description_uz_cyril = EXCLUDED.description_uz_cyril, description_kaa = EXCLUDED.description_kaa;

-- UASH (general_practitioner) -> FORM058_SENDER: READ, CREATE INSERT INTO role_permissions (role_id, permission_id, version, created_at, updated_at) SELECT r.id, p.id, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM role r, permission p WHERE r.name = 'isemid_general_practitioner' AND p.subject = 'FORM058_SENDER' ON CONFLICT (role_id, permission_id) DO NOTHING;
INSERT INTO role_permission_actions (role_permission_id, action_id) SELECT rp.id, a.id FROM role_permissions rp JOIN role r ON r.id = rp.role_id JOIN permission p ON p.id = rp.permission_id JOIN action a ON a.code IN ('READ', 'CREATE') WHERE r.name = 'isemid_general_practitioner' AND p.subject = 'FORM058_SENDER' ON CONFLICT (role_permission_id, action_id) DO NOTHING;
