INSERT INTO role_permission_actions (role_permission_id, action_id) SELECT rp.id, a.id FROM role_permissions rp JOIN role r ON r.id = rp.role_id JOIN permission p ON p.id = rp.permission_id JOIN action a ON a.code IN ('READ', 'CARD_ATTACH', 'ORG_CHANGE', 'FORM_CANCEL') WHERE r.name = 'isemid_epidim_head' AND p.subject = 'FORM058_RECEIVER' ON CONFLICT (role_permission_id, action_id) DO NOTHING;
