-- Super Admin -> barcha subject INSERT INTO role_permissions (role_id, permission_id, version, created_at, updated_at) SELECT r.id, p.id, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM role r CROSS JOIN permission p WHERE r.name = 'isemid_super_admin' AND p.deleted = false ON CONFLICT (role_id, permission_id) DO NOTHING;
-- Super Admin -> barcha action (DELETE va MANAGE bilan birga) INSERT INTO role_permission_actions (role_permission_id, action_id) SELECT rp.id, a.id FROM role_permissions rp JOIN role r ON r.id = rp.role_id CROSS JOIN action a WHERE r.name = 'isemid_super_admin' AND a.deleted = false ON CONFLICT (role_permission_id, action_id) DO NOTHING;
-- Admin -> barcha subject INSERT INTO role_permissions (role_id, permission_id, version, created_at, updated_at) SELECT r.id, p.id, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM role r CROSS JOIN permission p WHERE r.name = 'isemid_admin' AND p.deleted = false ON CONFLICT (role_id, permission_id) DO NOTHING;
-- Admin -> DELETE va MANAGE'dan tashqari barcha action INSERT INTO role_permission_actions (role_permission_id, action_id) SELECT rp.id, a.id FROM role_permissions rp JOIN role r ON r.id = rp.role_id CROSS JOIN action a WHERE r.name = 'isemid_admin' AND a.deleted = false AND a.code NOT IN ('DELETE', 'MANAGE') ON CONFLICT (role_permission_id, action_id) DO NOTHING;
